 private final Matrix mapProjection=new Matrix();
 RealmHud(){mapProjection.setValues(new float[]{1,-1,0,.5f,.5f,0,0,0,1});}
 private final Paint p=new Paint(3);private final Path clip=new Path();private final SurvivorAtlas portrait=new SurvivorAtlas();private final HashSet<String> explored=new HashSet<>();private JSONObject cachedVisibility;private Bitmap minimapBitmap;private Canvas minimapCanvas;private long minimapAt;private String minimapRoom="";
 private void text(Canvas c,String s,float x,float y,float size,int color){p.setColor(color);p.setTextSize(size);p.setStyle(Paint.Style.FILL);c.drawText(s,x,y,p);}
 private void bar(Canvas c,float x,float y,float width,double value,double max,int color){p.setColor(0xdd111814);c.drawRect(x,y,x+width,y+10,p);p.setColor(color);c.drawRect(x+2,y+2,x+2+(width-4)*(float)Math.max(0,Math.min(1,value/Math.max(1,max))),y+8,p);}
 private boolean known(JSONObject view,double x,double y){int cell=view==null?75:view.optInt("cellSize",75);return explored.contains((int)Math.floor(x/cell)+","+(int)Math.floor(y/cell));}
 void draw(Canvas canvas,JSONObject state,float width,float unit,float dx,float dy,float renderedX,float renderedY){JSONObject you=state.optJSONObject("you");if(you==null)return;Canvas c=canvas;c.save();c.scale(unit,unit);float w=width/unit;
 p.setColor(0xcc101713);c.drawRoundRect(10,7,279,98,10,10,p);p.setColor(0xffa99160);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.5f);c.drawRoundRect(10,7,279,98,10,10,p);p.setStyle(Paint.Style.FILL);
 portrait.headshot(c,you,13,10,75,79);text(c,"LV "+you.optInt("level",1),24,91,10,0xffd7c599);
 text(c,"HEALTH  "+you.optInt("hp")+" / "+you.optInt("maxHp",100),85,26,11,0xffeee1c6);bar(c,85,32,180,you.optDouble("hp"),you.optDouble("maxHp",100),0xffa93c35);
 text(c,"STAMINA  "+you.optInt("stamina"),85,60,11,0xffeee1c6);bar(c,85,66,180,you.optDouble("stamina"),you.optDouble("maxStamina",100),0xff649a59);
 text(c,"Food "+you.optInt("hunger")+"  Water "+you.optInt("thirst")+"  "+(you.optDouble("temperature",50)<25?"COLD":you.optDouble("temperature",50)>75?"HOT":"Comfort"),85,88,10,0xffc0bda7);
 float compassLeft=292,compassRight=w-212,center=(compassLeft+compassRight)/2;float heading=(float)((Math.toDegrees(Math.atan2(dx,-dy))+360)%360);String[] dirs={"N","NE","E","SE","S","SW","W","NW"};c.save();c.clipRect(compassLeft,6,compassRight,62);p.setColor(0xbb101713);c.drawRect(compassLeft,6,compassRight,62,p);
 for(int i=-8;i<=8;i++){float angle=(float)(Math.floor(heading/15)*15+i*15),delta=angle-heading,x=center+delta*2;int bearing=((int)angle%360+360)%360;p.setColor(0xffbca776);c.drawRect(x,10,x+1,bearing%45==0?19:15,p);text(c,bearing%45==0?dirs[bearing/45]:""+bearing,x-7,32,bearing%45==0?12:9,0xffe4d4ae);}
 text(c,"▼",center-5,45,13,0xffdfb86c);text(c,state.optBoolean("protected")?"SAFE TOWN":"WILDERNESS",center-38,58,9,0xffc7c8ac);c.restore();
 JSONObject account=state.optJSONObject("account");text(c,"GOLD "+(account==null?you.optLong("gold"):account.optLong("gold")),w-204,25,13,0xffe6bc64);
 JSONObject time=state.optJSONObject("gameTime");if(time!=null)text(c,time.optString("label")+"  "+time.optString("phase"),w-204,44,10,0xffd4c6a7);
 long now=android.os.SystemClock.uptimeMillis();String room=you.optString("interior","");if(minimapBitmap==null){minimapBitmap=Bitmap.createBitmap(300,300,Bitmap.Config.ARGB_8888);minimapCanvas=new Canvas(minimapBitmap);}
 if(now-minimapAt>=100||!room.equals(minimapRoom)||minimapAt==0){minimapAt=now;minimapRoom=room;minimapBitmap.eraseColor(Color.TRANSPARENT);minimapCanvas.save();minimapCanvas.scale(2,2);minimap(minimapCanvas,state,you,75,75,65,heading,renderedX,renderedY);minimapCanvas.restore();}p.setColor(Color.WHITE);c.drawBitmap(minimapBitmap,null,new RectF(w-153,9,w-3,159),p);c.restore();}
 private void minimap(Canvas c,JSONObject state,JSONObject you,float cx,float cy,float radius,float heading,float renderedX,float renderedY){double px=renderedX,py=renderedY;float scale=radius/850;JSONObject view=state.optJSONObject("visibility");if(view!=cachedVisibility){cachedVisibility=view;explored.clear();JSONArray cells=view==null?null:view.optJSONArray("explored");if(cells!=null)for(int i=0;i<cells.length();i++)explored.add(cells.optString(i));}
 clip.reset();clip.addCircle(cx,cy,radius,Path.Direction.CW);c.save();c.clipPath(clip);p.setColor(0xff080d0a);c.drawCircle(cx,cy,radius,p);c.translate(cx,cy);c.scale(scale,scale);c.concat(mapProjection);c.translate(-(float)px,-(float)py);
 if(you.optString("interior","").isEmpty()||you.optString("interior").equals("null")){JSONObject atlas=state.optJSONObject("worldMap");JSONArray shapes=atlas==null?state.optJSONArray("terrainPolygons"):atlas.optJSONArray("terrainPolygons");terrain.map(c,shapes,49920,33280);
 lines(c,state.optJSONArray("roads"),view,px,py,0xff65583d,36);lines(c,state.optJSONArray("roads"),view,px,py,0xffc2ad79,20);lines(c,state.optJSONArray("streams"),view,px,py,0xff315567,40);lines(c,state.optJSONArray("streams"),view,px,py,0xff76a6b5,25);
 JSONArray buildings=state.optJSONArray("village");if(buildings!=null)for(int i=0;i<buildings.length();i++){JSONObject b=buildings.optJSONObject(i);float x=(float)b.optDouble("x"),y=(float)b.optDouble("y");if(!known(view,x,y)||Math.hypot(x-px,y-py)>1200)continue;p.setColor(0xffa79672);float bw=(float)b.optDouble("halfWidth",25),depth=(float)b.optDouble("depth",25);c.drawRoundRect(x-bw,y-depth,x+bw,y+8,6,6,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(7);p.setColor(0xff403e31);c.drawRoundRect(x-bw,y-depth,x+bw,y+8,6,6,p);p.setStyle(Paint.Style.FILL);p.setStrokeWidth(5);p.setColor(0xffd1bd8c);c.drawLine(x,y-depth+5,x,y+3,p);String shop=b.optString("shop","");if(!shop.isEmpty()&&!shop.equals("null")){p.setColor(0xffe4c66d);c.drawCircle(x,y,28,p);text(c,shop.toLowerCase().contains("bank")?"B":shop.toLowerCase().contains("smith")?"S":shop.equals("MISSIONS")?"M":"•",x-15,y+12,35,0xff171e17);}}
 }else{JSONObject room=state.optJSONObject("room");p.setColor(0xff625b48);c.drawRect(0,0,room==null?600:room.optInt("width",600),room==null?500:room.optInt("height",500),p);}
 for(String group:new String[]{"enemies","players","companions"}){JSONArray actors=state.optJSONArray(group);if(actors==null)continue;p.setColor(group.equals("enemies")?0xffcf6355:group.equals("players")?0xff8fb8dd:0xffb6cc79);for(int i=0;i<actors.length();i++){JSONObject a=actors.optJSONObject(i);c.drawCircle((float)a.optDouble("x"),(float)a.optDouble("y"),17,p);}}
 c.restore();p.setColor(0xffb39a67);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);c.drawCircle(cx,cy,radius,p);p.setStyle(Paint.Style.FILL);text(c,"N",cx+radius*.82f-4,cy-radius*.41f+4,11,0xffeee0b7);c.save();c.translate(cx,cy);float rad=(float)Math.toRadians(heading),wx=(float)Math.sin(rad),wy=-(float)Math.cos(rad);c.rotate((float)Math.toDegrees(Math.atan2(CombatAim.screenX(wx,wy),-CombatAim.screenY(wx,wy))));p.setColor(0xffa9df97);clip.reset();clip.moveTo(0,-8);clip.lineTo(-5,6);clip.lineTo(0,3);clip.lineTo(5,6);clip.close();c.drawPath(clip,p);c.restore();}
 private void lines(Canvas c,JSONArray lines,JSONObject view,double px,double py,int color,float width){if(lines==null)return;p.setColor(color);p.setStrokeWidth(width);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);for(int i=0;i<lines.length();i++){JSONObject line=lines.optJSONObject(i);p.setStrokeWidth((float)line.optDouble("width",width));JSONArray points=line.optJSONArray("points");if(points==null)continue;for(int j=1;j<points.length();j++){JSONObject a=points.optJSONObject(j-1),b=points.optJSONObject(j);float ax=(float)a.optDouble("x"),ay=(float)a.optDouble("y"),bx=(float)b.optDouble("x"),by=(float)b.optDouble("y");if(Math.min(ax,bx)>px+1200||Math.max(ax,bx)<px-1200||Math.min(ay,by)>py+1200||Math.max(ay,by)<py-1200)continue;int steps=Math.min(200,(int)Math.ceil(Math.hypot(bx-ax,by-ay)/40));for(int k=0;k<steps;k++){float x=ax+(bx-ax)*k/steps,y=ay+(by-ay)*k/steps,xx=ax+(bx-ax)*(k+1)/steps,yy=ay+(by-ay)*(k+1)/steps;if(known(view,x,y)&&known(view,xx,yy))c.drawLine(x,y,xx,yy,p);}}}}
